INSERT INTO public.opportunities (title, company_name, employment_type, location, mode, stipend_or_salary, experience_required, skills_required, description, application_link, deadline, is_active, department, experience_level, salary_range_min, salary_range_max, status, posted_date, requirements, responsibilities, benefits, applications_count, messages_count, views_count, job_title, schedule_note, recruiter_id, created_by, created_by_uuid, organization_id)
SELECT s.title, s.company_name, s.employment_type, s.location, s.mode, s.stipend_or_salary, s.experience_required, s.skills_required, s.description, s.application_link, s.deadline, s.is_active, s.department, s.experience_level, s.salary_range_min, s.salary_range_max, s.status, s.posted_date, s.requirements, s.responsibilities, s.benefits, s.applications_count, s.messages_count, s.views_count, s.job_title, s.schedule_note,
       owner.recruiter_id,
       owner.created_by_uuid::text,
       owner.created_by_uuid,
       owner.organization_id
FROM seed_rows s
CROSS JOIN owner
WHERE NOT EXISTS (
  SELECT 1
  FROM public.opportunities existing
  WHERE lower(existing.company_name) = lower(s.company_name)
    AND lower(existing.job_title) = lower(s.job_title)
    AND lower(existing.location) = lower(s.location)
    AND COALESCE(existing.application_link, '') = COALESCE(s.application_link, '')
);

COMMIT;
